<?php
/** Real 1,738-product benchmark; isolated Woo DB only. No invented timings. */
use Exin\BlackFriday\Infrastructure\CampaignRepository;
use Exin\BlackFriday\Infrastructure\Logger;
use Exin\BlackFriday\Application\ProductSelectionService;
use Exin\BlackFriday\Application\PriceProcessor;
use Exin\BlackFriday\Application\Scheduler;
use Exin\BlackFriday\Application\AdaptiveAnalytics;
use Exin\BlackFriday\Domain\DiscountPlan;
if(!defined('WP_CLI')||!WP_CLI||DB_NAME!=='exin_test'||wp_get_environment_type()!=='local')throw new RuntimeException('Local only');
global$wpdb;$repo=new CampaignRepository();$selection=new ProductSelectionService($repo);$processor=new PriceProcessor($repo,new Logger());$scheduler=new Scheduler($repo,$processor,new Logger());$analytics=new AdaptiveAnalytics($repo);
update_option('woocommerce_currency','USD');update_option('woocommerce_price_num_decimals',2);add_filter('action_scheduler_allow_async_request_runner','__return_false');add_filter('pre_wp_mail','__return_true');
$measure=static function(callable$fn){$q=get_num_queries();if(function_exists('memory_reset_peak_usage'))memory_reset_peak_usage();$t=microtime(true);$value=$fn();return ['seconds'=>round(microtime(true)-$t,6),'queries'=>get_num_queries()-$q,'peak_bytes'=>memory_get_peak_usage(true),'result'=>$value];};
$plan=DiscountPlan::normalize(['mode'=>'smart_adaptive','interval'=>'hourly','interval_minutes'=>120,'duration_minutes'=>10080,'seed'=>'isolated-scale-1738','adaptive'=>['exploration_bps'=>0]],2);
$c=['title'=>'EXIN1738 '.wp_generate_uuid4(),'start_utc'=>gmdate('Y-m-d H:i:s',time()-172805),'timezone'=>'UTC','days'=>7,'strategy'=>'linear','power'=>2,'rounding'=>'half_up','settings'=>['discount_plan'=>$plan,'existing_sale_policy'=>'preserve']];$c['end_utc']=DiscountPlan::end($c);$id=$repo->create($c);$ids=[];
$setup=$measure(static function()use($id,$selection,&$ids){for($i=0;$i<1738;$i++){$p=new WC_Product_Simple();$p->set_name('EXIN1738 '.$i);$p->set_status('publish');$p->set_virtual(true);$p->set_regular_price('100');$p->set_manage_stock(true);$p->set_stock_quantity(100);$p->save();$selection->add($id,$p->get_id(),$i%2?'60':'50');$ids[]=$p->get_id();if($i%250===0)echo 'FIXTURE '.($i+1).PHP_EOL;}return count($ids);});
$repo->save($id,['status'=>'active']);$c=$repo->get($id);$version=$c['version'];(new Exin\BlackFriday\Application\AutomaticSelection($repo))->capacity($c,1738);
$before=$wpdb->get_results($wpdb->prepare('SELECT product_id,floor_price,floor_override,snapshot FROM %i WHERE campaign_id=%d ORDER BY product_id',$wpdb->prefix.'exin_bf_items',$id),ARRAY_A);
$initial=$measure(static function()use($analytics,$id,$wpdb){$passes=0;do{$analytics->run($id);$passes++;$count=(int)$wpdb->get_var($wpdb->prepare('SELECT COUNT(*) FROM %i WHERE campaign_id=%d AND revision=validated_revision',$wpdb->prefix.'exin_bf_adaptive_metrics',$id));}while($count<1738&&$passes<30);if($count!==1738)throw new RuntimeException('Missing metric snapshots');return ['passes'=>$passes,'snapshots'=>$count];});
wp_cache_flush();$order_queries=0;$sales_aggregates=0;$tracking=false;
add_filter('woocommerce_order_query_args',static function($q)use(&$order_queries,&$tracking){if($tracking)$order_queries++;return$q;});add_filter('query',static function($sql)use(&$sales_aggregates,&$tracking){if($tracking&&preg_match('/(?:SUM\(|adaptive_sales)/i',$sql))$sales_aggregates++;return$sql;});
$tracking=true;$pricing=$measure(static function()use($scheduler,$id,$version,$repo){$n=0;do{$scheduler->batch($id,$version);$n++;$run=$repo->get($id)['settings']['last_run']??[];}while(empty($run['complete'])&&$n<100);return ['batches'=>$n,'run'=>$run['complete']??false];});$tracking=false;
if($order_queries||$sales_aggregates)throw new RuntimeException('Pricing scanned or aggregated sales');
$violations=(int)$wpdb->get_var($wpdb->prepare("SELECT COUNT(*) FROM %i i JOIN %i p ON p.product_id=i.product_id WHERE i.campaign_id=%d AND (CAST(i.floor_price AS DECIMAL(30,8))<=0 OR p.min_price<CAST(i.floor_price AS DECIMAL(30,8)) OR p.min_price>CAST(i.base_price AS DECIMAL(30,8)))",$wpdb->prefix.'exin_bf_items',$wpdb->prefix.'wc_product_meta_lookup',$id));if($violations)throw new RuntimeException('Floor violation');
// Three real attributed orders. Every repeated delivery must still count once.
$orders=[];foreach([2,1,1]as$qty){$o=wc_create_order();$o->set_currency('USD');$line_id=$o->add_product(wc_get_product($ids[0]),$qty);$line=$o->get_item($line_id);$line->add_meta_data('_exin_bf_campaign_id',$id,true);$line->add_meta_data('_exin_bf_product_id',$ids[0],true);$line->save();$o->update_meta_data('_exin_bf_campaign_'.$id,'1');$o->calculate_totals();$o->save();$o->update_status('completed');$orders[]=$o->get_id();}
$events=$measure(static function()use($analytics,$id){$analytics->run($id);return true;});
$gate=sys_get_temp_dir().'/exin-hardening-'.wp_generate_uuid4();$env=getenv();$env['EXIN_HARDEN_CID']=(string)$id;$env['EXIN_HARDEN_PID']=(string)$ids[0];$env['EXIN_HARDEN_OID']=(string)$orders[0];$env['EXIN_HARDEN_VERSION']=(string)$version;$env['EXIN_HARDEN_GATE']=$gate;
$root=dirname(__DIR__,2);$cmd=[$root.'/scripts/php-v101.sh',$root.'/work/runtime/wp-cli.phar','--path='.getenv('EXIN_NATIVE_WP'),'--allow-root','eval-file',$root.'/tests/integration/v140-scale-worker.php'];$children=[];
$concurrent=$measure(static function()use($env,$cmd,$gate,&$children){$procs=[];$pipes=[];foreach(['status','refund','analytics','pricing']as$i=>$role){$e=$env;$e['EXIN_HARDEN_ROLE']=$role;$procs[$i]=proc_open($cmd,[0=>['pipe','r'],1=>['pipe','w'],2=>['pipe','w']],$pipes[$i],null,$e);fclose($pipes[$i][0]);}file_put_contents($gate,'go');foreach($procs as$i=>$p){$out=stream_get_contents($pipes[$i][1]);$err=stream_get_contents($pipes[$i][2]);fclose($pipes[$i][1]);fclose($pipes[$i][2]);$exit=proc_close($p);if($exit)throw new RuntimeException('Concurrent worker failed '.$err);preg_match('/HARDEN_CHILD (.+)/',$out,$m);if(!$m)throw new RuntimeException($out);$children[]=json_decode($m[1],true,512,JSON_THROW_ON_ERROR);}@unlink($gate);return true;});
$analytics->run($id);$analytics->run($id);wp_cache_flush();$units=(int)$wpdb->get_var($wpdb->prepare('SELECT SUM(units) FROM %i WHERE campaign_id=%d AND product_id=%d',$wpdb->prefix.'exin_bf_adaptive_sales',$id,$ids[0]));$count=(int)$wpdb->get_var($wpdb->prepare('SELECT COUNT(*) FROM %i WHERE campaign_id=%d AND product_id=%d',$wpdb->prefix.'exin_bf_adaptive_sales',$id,$ids[0]));file_put_contents(dirname(__DIR__,2).'/work/v140/scale-partial.json',wp_json_encode(['campaign'=>$id,'setup'=>$setup,'initial'=>$initial,'pricing'=>$pricing,'events'=>$events,'children'=>$children,'units'=>$units,'count'=>$count]));if($units!==3||$count!==3)throw new RuntimeException('Duplicated or stale sales '.$units.'/'.$count);
$after=$wpdb->get_results($wpdb->prepare('SELECT product_id,floor_price,floor_override,snapshot FROM %i WHERE campaign_id=%d ORDER BY product_id',$wpdb->prefix.'exin_bf_items',$id),ARRAY_A);if($before!==$after)throw new RuntimeException('Original financial fields changed');
$hold=$measure(static function()use($wpdb,$id,$ids,$processor,$version,$repo){$c=$repo->get($id);$c['start_utc']=gmdate('Y-m-d H:i:s',time()-180005);$repo->save($id,['start_utc'=>$c['start_utc'],'end_utc'=>DiscountPlan::end($c)]);$wpdb->update($wpdb->prefix.'exin_bf_adaptive_metrics',['validated_revision'=>0],['campaign_id'=>$id,'product_id'=>$ids[0]]);$p=wc_get_product($ids[0]);$old=$p->get_price('edit');$processor->apply($id,$ids[0],$version);$new=wc_get_product($ids[0])->get_price('edit');if($old!==$new)throw new RuntimeException('Unavailable metrics did not hold safe price');return true;});
$report=['products'=>1738,'campaign_id'=>$id,'duration_days'=>7,'evaluation_minutes'=>120,'database'=>$wpdb->db_version(),'php'=>PHP_VERSION,'fixture'=>$setup,'initial_analytics'=>$initial,'pricing'=>$pricing,'event_processing'=>$events,'concurrency_parent'=>$concurrent,'concurrent_children'=>$children,'missing_metrics_hold'=>$hold,'pricing_order_queries'=>$order_queries,'pricing_sales_aggregates'=>$sales_aggregates,'floor_violations'=>$violations,'sales_units_after_refund'=>$units,'distinct_valid_orders'=>$count,'financial_fields_unchanged'=>true,'measurement'=>'single isolated Native run; parent queries exclude child queries, which are separately reported'];
file_put_contents($root.'/work/v140/scale-hardening.json',wp_json_encode($report,JSON_PRETTY_PRINT));echo 'EXIN_SCALE_RESULT '.wp_json_encode($report).PHP_EOL;
